import random

def has_cycle_of_length(edges, n, length):
    """Check if graph has a cycle of given length."""
    adj = [[] for _ in range(n)]
    for u, v in edges:
        adj[u].append(v)
        adj[v].append(u)

    # BFS/DFS to find cycles of specific length
    # For small lengths, we can enumerate
    if length == 3:
        for u in range(n):
            for v in adj[u]:
                if v > u:
                    for w in adj[v]:
                        if w > v and w in adj[u]:
                            return True
        return False

    # For longer cycles, use DFS
    def dfs(start, current, path, visited):
        if len(path) == length:
            if start in adj[current]:
                return True
            return False
        for neighbor in adj[current]:
            if neighbor == start and len(path) == length - 1:
                return True
            if neighbor not in visited and neighbor != start:
                visited.add(neighbor)
                path.append(neighbor)
                if dfs(start, neighbor, path, visited):
                    return True
                path.pop()
                visited.remove(neighbor)
        return False

    for start in range(n):
        visited = {start}
        if dfs(start, start, [start], visited):
            return True
    return False

def has_short_cycle(edges, n, max_length=7):
    """Check if graph has any cycle of length 3 to max_length."""
    for length in range(3, max_length + 1):
        if has_cycle_of_length(edges, n, length):
            return True
    return False

