def has_cycle_of_length(edges, n, length):
    """Check if graph has a cycle of given length using BFS from each vertex."""
    adj = [[] for _ in range(n)]
    for u, v in edges:
        adj[u].append(v)
        adj[v].append(u)

    # For each starting vertex, do BFS to find cycles
    for start in range(n):
        # BFS: (current, path)
        queue = [(start, [start])]
        visited_at_depth = {start: 0}

        while queue:
            current, path = queue.pop(0)
            if len(path) > length:
                continue
            for neighbor in adj[current]:
                if neighbor == start and len(path) == length:
                    return True
                if neighbor not in visited_at_depth or visited_at_depth[neighbor] > len(path):
                    if len(path) < length:
                        visited_at_depth[neighbor] = len(path)
                        queue.append((neighbor, path + [neighbor]))
    return False

